{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Despite their importance and wide application, the quality of meta-analyses is highly variable [1,7,10,11]. If the quality of meta-analyses is poor, it is hard to know if 'biological metaanalysis embodies 'mega-enlightenment', a 'mega-mistake', or something in between' [12]. One issue that can prevent readers from evaluating the overall quality of a published metaanalysis is the lack of details describing each step in the meta-analysis.",
      "reason": "The Introduction describes the current state of knowledge (increasing number of meta-analyses, variable quality, reporting/execution issues) and key uncertainties about reliability of ecological meta-analyses."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Assessing the current compliance with recommended steps for reporting and execution in ecological meta-analyses and identifying places that need improvements can help guide the meta-analytic community towards more robust inference and reduce controversy. In this paper, we reviewed the literature assessing the quality of ecological meta-analyses, collected new data to evaluate current practices, and highlight the areas that need more work.",
      "reason": "The importance and need for the review are explicitly explained: assessing compliance and identifying gaps can guide the community toward more robust inference."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "First, we compiled information from 18 studies in the last 20 years (between 2002 and 2022) that reviewed the quality of meta-analyses in ecology, evolution and related fields. These papers provided different insights on the compliance with different standards of reporting quality and with recommended execution steps... Second, we evaluated the recognition and treatment of non-independence for the ecological meta-analyses included in Pappalardo et al. [1], and extracted new data on quality criteria to compare it with the other reviews.",
      "reason": "Previous reviews are identified and cited (18 review papers, Pappalardo et al.), and the current review's added value (new data, re-analysis, synthesis across reviews) is described, but an explicit statement of why prior reviews were insufficient on their own is only implicit."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a meta-evaluation of reporting/execution quality in ecological meta-analyses, not a review of intervention effects; no intervention mechanism applies."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No complex intervention or delivery context is involved; a logic model is not relevant to this meta-evaluation of meta-analysis quality."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "In this paper, we reviewed the literature assessing the quality of ecological meta-analyses, collected new data to evaluate current practices, and highlight the areas that need more work. First, we compiled information from 18 studies in the last 20 years (between 2002 and 2022) that reviewed the quality of meta-analyses in ecology, evolution and related fields. ... Second, we evaluated the recognition and treatment of non-independence for the ecological meta-analyses included in Pappalardo et al. [1] ... Finally, we summarized the level of compliance for different quality criteria across these 18 previous meta-analysis reviews and the new data taken from papers reviewed in Pappalardo et al [1].",
      "reason": "The Introduction explicitly states the review's objectives as three enumerated aims, and the Abstract restates them ('We reviewed the literature assessing the quality of ecological meta-analyses to evaluate current practices and highlight areas that need improvement')."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "In this paper, we reviewed the literature assessing the quality of ecological meta-analyses, collected new data to evaluate current practices, and highlight the areas that need more work.",
      "reason": "This is a meta-evaluation of the quality of reporting and execution in ecological meta-analyses, not a review of intervention effects; no planned intervention comparisons exist, so PICO-style framing does not apply."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "we surveyed the literature for quantitative assessments on criteria previously identified as best practices in meta-analysis... the majority were excluded for not having quantitative data on the selected criteria (Fig 1). One paper was excluded for being out of scope.",
      "reason": "Eligibility is partly specified (papers must be quantitative assessments of meta-analysis quality criteria; exclusions for lacking quantitative data and being out of scope), but full study-design/settings/follow-up type criteria are not systematically enumerated."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No report characteristics such as publication year range, language, or publication status restrictions for included review papers are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No distinction is made between exclusion because quality/compliance outcomes were not measured versus outcomes measured but results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "These criteria fall into two broad categories: 1) execution (i.e., methodological issues related with best practices for data analysis), and 2) reporting (i.e., details describing each step of the meta-analysis and providing the data and information needed to allow for reproducibility).",
      "reason": "The syntheses group studies/criteria into Reporting and Execution categories, explicitly defined and linked to the review objective of evaluating current practices in conducting and reporting ecological meta-analyses; Table 2 further details criterion groupings."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "To reduce non-independence in our compilation, we kept only [15] that had information for six of our selected criteria; i.e., we excluded [14] from our analyses.",
      "reason": "A rationale (avoiding non-independence) is provided for the notable restriction of excluding one of two overlapping review papers."
    }
  ],
  "confidence": 78
}

